content.text:
{
  "name": "LabJack U12 数据采集设备",
  "name_en": "LabJack U12 Data Acquisition Device",
  "manufacturer": "LabJack",
  "description": "LabJack U12 是一款 USB 数据采集设备，可进行模拟量输入、差分模拟输入、模拟量输出和数字输入/输出，适用于实验中的电压采集、低噪声差分测量、简单信号输出以及开关量控制。",
  "description_en": "The LabJack U12 is a USB data acquisition device that supports analog input, differential analog input, analog output, and digital input/output. It is used in laboratories for voltage acquisition, low-noise differential measurements, simple signal output, and digital switching/control.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化 U12 设备连接。",
      "description_en": "Initialize the U12 device connection."
    },
    {
      "action_name": "auto-finalize",
      "description": "关闭并结束 U12 设备连接。",
      "description_en": "Close and finalize the U12 device connection."
    },
    {
      "action_name": "auto-analog_in",
      "description": "读取指定通道的单端模拟输入电压。",
      "description_en": "Read the single-ended analog input voltage from the specified channel."
    },
    {
      "action_name": "auto-analog_dif_in",
      "description": "读取指定通道的差分模拟输入电压，并可设置增益。",
      "description_en": "Read the differential analog input voltage from the specified channel, with configurable gain."
    },
    {
      "action_name": "auto-analog_out",
      "description": "设置指定模拟输出通道的输出电压。",
      "description_en": "Set the output voltage of the specified analog output channel."
    },
    {
      "action_name": "auto-digital_in_out",
      "description": "读取指定数字引脚输入状态，或设置其数字输出状态。",
      "description_en": "Read the input state of a specified digital pin, or set its digital output state."
    },
    {
      "action_name": "auto-U12",
      "description": "创建设备对象以控制 LabJack U12 数据采集设备。",
      "description_en": "Create a device object for controlling the LabJack U12 data acquisition device."
    }
  ],
  "tag_hints": [
    "USB DAQ",
    "LabJack U12",
    "analog input",
    "differential measurement",
    "analog output",
    "digital I/O",
    "voltage acquisition"
  ]
}

